// VULNERABLE : aucune verification de proprietaire
app.get('/factures/:id', requireAuth, async (req, res) => {
  const facture = await db.factures.findById(req.params.id)
  res.json(facture) // renvoie la facture de n'importe qui
})

// CORRIGE : on verifie que la facture appartient a l'appelant
app.get('/factures/:id', requireAuth, async (req, res) => {
  const facture = await db.factures.findById(req.params.id)
  if (!facture || facture.ownerId !== req.user.id) {
    return res.status(404).json({ error: 'Introuvable' }) // ni fuite, ni indice
  }
  res.json(facture)
})

